let report;
const $=selector=>document.querySelector(selector);
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={random:'随机初始化',warmup:'共享热身模型',sft:'全参数 SFT',lora:'LoRA',chosen_sft:'chosen-only SFT',dpo:'DPO',dpo_anchor:'DPO + 辅助 SFT',simpo:'SimPO',ppo:'PPO',grpo:'GRPO',distill:'筛选与序列蒸馏'};
const number=(value,digits=4)=>Number.isFinite(value)?value.toFixed(digits):'—';
export function practicePage(){
 return `<div class="eyebrow">FROM FORMULAS TO TRAINING</div><h1 class="lesson-title">让一条训练流程，真正跑起来。</h1><p class="lesson-intro">在 CPU 上训练一个微型因果 Transformer，把数据、loss、梯度和生成结果连接起来。</p><div class="notice">这里展示 Python 实际运行保存的记录，浏览器不启动训练。模型只有约 1.9 万参数，任务是复制符号；这些结果不代表大模型安全 benchmark，也不能用来给算法排名。</div><div class="button-row" style="margin-bottom:26px"><a class="btn primary" href="./downloads/safeposttrain-tiny-lm.zip" download>下载 PyTorch 实战包 ↓</a><a class="btn" href="./content/tiny-lm-report.json" download>下载完整运行记录 ↓</a><a class="btn ghost" href="#/guide/study">学习顺序与作业</a></div><div id="practice-root"><p role="status">正在打开真实运行记录…</p></div>`;
}
function lossChart(history){
 if(!history?.length)return '<p class="lab-note">该阶段没有优化步骤，用作对照起点。</p>';
 const width=560,height=160,pad=28,values=history.map(x=>x.loss_before_update),min=Math.min(...values),max=Math.max(...values),span=max-min||1,last=history.at(-1).step;
 const points=history.map(x=>`${pad+x.step/last*(width-pad*2)},${height-pad-(x.loss_before_update-min)/span*(height-pad*2)}`).join(' ');
 return `<svg viewBox="0 0 ${width} ${height}" class="plot" role="img" aria-label="当前阶段 loss 随优化步变化"><line x1="${pad}" x2="${width-pad}" y1="${height-pad}" y2="${height-pad}" stroke="#cbd5c4"/><polyline points="${points}" fill="none" stroke="#315f43" stroke-width="2.5"/><text x="${pad}" y="15" fill="#6d786f" font-size="10">${number(max,3)}</text><text x="${pad}" y="${height-8}" fill="#6d786f" font-size="10">${number(min,3)}</text><text x="${width-100}" y="${height-8}" fill="#6d786f" font-size="10">${last} 次更新</text></svg><p class="lab-note">点是更新前记录的训练 loss。各方法的目标和量纲不同，这张曲线只用于观察当前阶段。</p>`;
}
function resultHTML(){
 const stage=report.stages.find(x=>x.name===$('#practice-method').value),split=$('#practice-split').value,e=stage[split],t=stage.training;
 const cost=t?.total_optimizer_tensor_bytes??t?.optimizer_tensor_bytes;
 return `<div class="practice-metrics"><div><b>${e.correct_count}/${e.sample_count}</b><span>允许格式且复制正确</span></div><div><b>${number(e.brief_rate*100,1)}%</b><span>简短且正确</span></div><div><b>${number(e.brief_target_nll,3)}</b><span>简短目标 NLL</span></div></div><div class="practice-panels"><section class="lab-output"><h2>训练过程</h2>${lossChart(t?.history)}${t?`<table class="table"><tr><th>可训练参数 ${t.critic_parameters?'（含 critic）':''}</th><td>${(t.total_trainable_parameters??t.parameters.trainable).toLocaleString()}</td></tr><tr><th>有效回答训练 token ${t.critic_parameters?'（actor）':''}</th><td>${t.effective_training_tokens.toLocaleString()}</td></tr><tr><th>阶段 CPU 耗时</th><td>${number(t.elapsed_seconds,3)} 秒</td></tr><tr><th>优化器张量 ${t.critic_parameters?'（含 critic）':''}</th><td>${number(cost/1024,1)} KiB</td></tr></table>`:''}<p class="lab-note">耗时受机器负载影响；优化器张量不含激活、权重副本和运行时开销，不是峰值内存。</p></section><section class="lab-output"><h2>与固定 SFT 参考的关系</h2><div class="formula">在同一批简短答案前缀上计算精确分布 KL</div><div class="metric-number">${number(e.kl_to_sft_on_brief_target_prefixes,4)}</div><p class="lab-note">KL 反映这些指定前缀上的分布差异，不能当成安全证明，也不是所有真实访问状态上的 KL。</p><details><summary>查看当前阶段原始训练日志</summary><pre class="practice-code">${escape(JSON.stringify(t?.history||[],null,2))}</pre></details></section></div><h2 class="practice-heading">逐条看生成结果</h2><p class="lab-note">以下每条都保留。允许 <code>符号 &lt;eos&gt;</code> 或 <code>answer 符号 &lt;eos&gt;</code>；简短率只计第一种正确回答。</p><div class="table-scroll"><table class="table output-table"><thead><tr><th>输入</th><th>模型生成</th><th>判定</th></tr></thead><tbody>${e.outputs.map(row=>`<tr><td>${escape(row.prompt.join(' '))}</td><td>${escape(row.generated.join(' '))}</td><td>${row.correct?'✓ 正确':'未完成任务'}</td></tr>`).join('')}</tbody></table></div>`;
}
function fullHTML(){
 const card=report.data_card;
 return `<section class="objectives"><h2>这次运行的边界</h2><ul><li>${report.model_parameters.toLocaleString()} 参数 · ${report.config.layers} 层 · ${report.config.heads} 个注意力头 · ${report.environment.torch_threads} 个 CPU 线程</li><li>${card.train_rows} 条训练数据 · ${card.development_rows} 条开发探针 · ${card.final_probe_rows} 条最终探针</li><li>三个集合共享符号/意图，只留出模板组合。开发探针已参与诊断。</li><li>种子 ${report.seed} · Python ${escape(report.environment.python)} · PyTorch ${escape(report.environment.torch)}</li></ul></section><section class="prose-section"><h2>先看一条数据，怎样变成监督信号</h2><p>只做一次因果位移。当前位置预测下一 token，用户与角色标记不贡献监督 loss，答案和 EOS 参与学习。</p><details><summary>展开真实 batch 的 token / label / mask</summary><div class="table-scroll"><table class="table"><thead><tr><th>位置</th><th>输入 token</th><th>下一 token</th><th>label</th><th>计入 loss</th></tr></thead><tbody>${report.mask_walkthrough.map(x=>`<tr><td>${x.position}</td><td>${escape(x.input)}</td><td>${escape(x.next_token)}</td><td>${x.label}</td><td>${x.supervised?'是':'否'}</td></tr>`).join('')}</tbody></table></div></details></section><section class="prose-section"><h2>选择一个阶段，追问发生了什么</h2><div class="practice-selectors"><label class="field" for="practice-method"><span>训练阶段</span><select id="practice-method">${report.stages.map(s=>`<option value="${s.name}" ${s.name==='sft'?'selected':''}>${names[s.name]}</option>`).join('')}</select></label><label class="field" for="practice-split"><span>评测集合</span><select id="practice-split"><option value="evaluation">开发探针（参与过诊断）</option><option value="final_evaluation">最终探针（配方冻结后）</option></select></label></div><div id="practice-results"></div></section><section class="prose-section"><h2>为什么保留 DPO 的失败？</h2><p>在这份教学配方中，DPO loss 下降，chosen 的概率却也下降；rejected 下降得更多，仍能让相对目标改善。开发探针上的模型甚至会直接输出 EOS。切换到 DPO，结合日志和逐条回答观察这一点。</p><p>DPO + 辅助 SFT 加入 0.2 倍 chosen 的监督损失，用作受控修复。chosen-only SFT 与 DPO 匹配有效回答 token 预算，但更新次数不同；SimPO 使用不同归一化与目标。这些对照帮助分析原因，不构成算法排名。</p></section><section class="prose-section"><h2>奖励模型和在线奖励，分别是什么？</h2><p>这里另训练了一个基于 Transformer 隐藏状态的评分模型。8 个开发偏好对的排序正确率为 ${number(report.reward_model.heldout.pair_accuracy*100,1)}%，正向偏好对的 Brier 值为 ${number(report.reward_model.heldout.brier_score,4)}。如此小的诊断集合不能证明普遍校准或抗长度偏差。</p><p>PPO/GRPO 使用的是精确任务验证器：简短正确为 1，较长正确为 0.5，错误为 0。它们没有使用上述奖励模型，因此这不是已接入神经 RM 的完整 RLHF。</p></section><section class="prose-section"><h2>生成 → 筛选 → 再训练</h2>${selectionHTML()}<p>学生与教师架构相同，演示的是序列蒸馏闭环，没有展示模型压缩。所有候选都保留在完整记录中，失败候选不会被标准答案替换。</p></section><section class="prose-section"><h2>在你的机器上复现</h2><p>本项目工作区已经准备隔离环境。下载包的 README 说明了其他 Linux 机器如何安装固定版本依赖；训练不下载外部模型或数据。</p><pre class="practice-code">.venv-teaching/bin/python -m labs.tiny_lm.run \
  --output artifacts/my-tiny-lm-run --seed 7

python3 labs/evaluate_measured.py</pre><p>最终探针需在配方冻结后通过 <code>--final-eval</code> 开启。保存后 logits 重载最大差值为 ${report.checkpoint_reload_max_logit_difference}；测试也验证了 actor/LoRA 的 AdamW 与 RNG 单步恢复，但未实现完整在线 PPO 续训。</p><div class="button-row"><a class="btn" href="./downloads/tiny-lm/README.md" download>详细实验说明 ↓</a><a class="btn ghost" href="#/guide/coverage">查看大纲覆盖与证据边界</a></div></section>`;
}
function selectionHTML(){const selection=report.stages.find(s=>s.name==='distill').selection;return `<p>教师先在训练侧通过 ${number(selection.gate_threshold*100,0)}% 质量门槛，实际选择 ${escape(names[selection.teacher]||selection.teacher)}。生成 ${selection.generated} 个候选，其中 ${selection.accepted} 个通过验证，按每个 prompt 第一条正确候选选中 ${selection.selected} 条训练学生。教师选择不读取开发或最终探针成绩。</p>`;}
export async function mountPractice(){
 const root=$('#practice-root');if(!root)return;
 try{if(!report){const response=await fetch('./content/tiny-lm-report.json');if(!response.ok)throw Error('report unavailable');report=await response.json();if(report.schema_version!==2||!report.stages.every(s=>s.final_evaluation))throw Error('incomplete report');}if(!root.isConnected)return;root.innerHTML=fullHTML();$('#practice-results').innerHTML=resultHTML();}
 catch{if(root.isConnected)root.innerHTML='<p role="alert">暂时无法加载实战记录。请刷新页面，或从源码包的 reports/tiny_lm 目录查看原始报告。</p>';}
}
document.addEventListener('change',event=>{if(['practice-method','practice-split'].includes(event.target.id)&&report&&$('#practice-results'))$('#practice-results').innerHTML=resultHTML();});
